var TimeProvider = require("@taf/taf-utils").timeProvider;
var ProtoMessage = require("../util/ProtoMessage");

//////////////////////////////////////////////////请求队列//////////////////////////////////////////////////////////////
var ReqMessage = function () {
    this.request        = new ProtoMessage.ProtoMessage();
    this.worker         = undefined;
    this.promise        = undefined;
    this.timer          = undefined;    //请求超时定时器
    this.adapter        = undefined;
    this.property       = undefined;
    this.costtime       = 0;            //本次请求完成的时间，单位毫秒
    this.startTime      = TimeProvider.nowTimestamp();            //本次请求开始的内部时间点
    this.LocalEndpoint  = undefined;    //本次调用本地地址
    this.RemoteEndpoint = undefined;    //本次调用远端地址
    this.location       = 0;            //0：默认；1：请求位于worker中；2：请求位于adapter中
};
module.exports.ReqMessage = ReqMessage;

ReqMessage.prototype.setTimeout = function (iTimeout) {
    var self = this;

    self.startTime = TimeProvider.nowTimestamp();
    self.timer     = setTimeout(function () {
        if(self.adapter && self.location == 2){
            self.adapter.doTimeout(self)
        }else{
            self.worker.doTimeout(self);
        }
    }, iTimeout);
};

ReqMessage.prototype.clearTimeout = function () {
    clearTimeout(this.timer);
    this.timer    = undefined;
    this.costtime = TimeProvider.nowTimestamp() - this.startTime;
};

ReqMessage.prototype.toObject = function(){
    return {
        request: {
            sFuncName: this.request.sFuncName,
            iRequestId: this.request.iRequestId,
            origin: {
                iRet: this.request.origin.iRet,
                sResultDesc: this.request.origin.sResultDesc
            }
        },
        property: this.property,
        costtime: this.costtime,
        LocalEndpoint: this.LocalEndpoint,
        RemoteEndpoint: this.RemoteEndpoint
    }
}

ReqMessage.getReqInfo = function(reqMessage) {
    var reqInfo = reqMessage
    if('toObject' in reqMessage){
        reqInfo = reqMessage.toObject()
    }
    return reqInfo
}
